#define _DEFAULT_SOURCE
#include <stdio.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

int main() {
    printf("Attempting to simulate virtual terminal hangup (vhangup())...\n");

    // vhangup() requires CAP_SYS_TTY_CONFIG capability, often requiring root access.
    if (vhangup() == 0) {
        printf("Success: Terminal virtually hung up.\n");
    } else {
        // Check for specific errors, particularly EPERM
        if (errno == EPERM) {
            fprintf(stderr, "Error: Insufficient privilege (EPERM).\n");
            fprintf(stderr, "vhangup requires CAP_SYS_TTY_CONFIG and is typically run by privileged processes.\n");
            return 1;
        } else {
            fprintf(stderr, "Error calling vhangup(): %s (errno %d)\n", strerror(errno), errno);
            return 1;
        }
    }
    return 0;
}
